contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We'll drive Put and fallback (via payable call to fallback) and observe balances.
    // Parameters: lock time and amount to send. amount is the ether forwarded to c.
    function run(uint lockTime, uint amount) public payable {
        require(address(this).balance >= amount);

        // Read before-values via public getters
        uint beforeHolderBalance = c.Acc(address(this)).balance;
        uint beforeContractBalance = address(c).balance;

        // Make the call that should increase balances: call Put with value `amount`.
        bool reverted;
        try c.Put{value: amount}(lockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint afterHolderBalance = c.Acc(address(this)).balance;
        uint afterContractBalance = address(c).balance;

        // If the call reverted, nothing in C should have changed; otherwise both holder and contract balances must have increased by exactly `amount`.
        assert(reverted ? (afterHolderBalance == beforeHolderBalance && afterContractBalance == beforeContractBalance)
                       : (afterHolderBalance == beforeHolderBalance + amount && afterContractBalance == beforeContractBalance + amount));
    }

    // Allow receiving refunds if necessary
    receive() external payable {}
}

