contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an amount to send and a lockTime for Put. We will call Put (or fallback via direct transfer)
    // and assert that when the call does not revert, the contract's recorded balance for this contract
    // increases by the amount sent and the contract's Ether balance increases accordingly.
    function run(uint lockTime, uint amount, bool useFallback) public payable {
        require(address(this).balance >= amount);

        // read before-values
        (, uint beforeBal) = c.Acc(address(this));
        uint beforeTotal = address(c).balance;

        bool reverted = false;
        if (useFallback) {
            // trigger fallback by sending plain Ether to c
            // must do low-level call to ensure fallback() runs and then Put(0) inside it
            (bool ok, ) = address(c).call{value: amount}("");
            reverted = !ok;
        } else {
            // call Put with provided lockTime and Ether
            try c.Put{value: amount}(lockTime) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // read after-values
        (, uint afterBal) = c.Acc(address(this));
        uint afterTotal = address(c).balance;

        // If the call did not revert, then the per-account stored balance must have increased by amount
        // and the contract's total balance must have increased by amount as well.
        assert(reverted || (afterBal == beforeBal + amount && afterTotal == beforeTotal + amount));
    }

    // allow receiving Ether so the test contract can fund itself off-chain before run()
    receive() external payable {}
}

