contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test Collect behavior: take amount to attempt to collect and a prior putAmount to fund the holder.
    // We first Put putAmount into c from this contract to ensure some balance (may revert if Put reverts).
    // Then we call Collect(amount) and observe whether it reverted. If Collect did not revert and the call
    // actually performed a transfer (i.e., preconditions in Collect were satisfied), then after the call
    // the Acc[this].balance and address(c).balance must have decreased by exactly amount and
    // address(this).balance must have increased by exactly amount.
    function run(uint putLock, uint putAmount, uint collectAmount) public payable {
        // ensure this contract can send putAmount when calling Put
        require(address(this).balance >= putAmount);

        // read before-values
        (, uint beforeAccBal) = c.Acc(address(this));
        uint beforeCbal = address(c).balance;
        uint beforeThisBal = address(this).balance;

        // perform Put to fund this test contract's holder entry
        bool putReverted;
        try c.Put{value: putAmount}(putLock) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // read values after Put
        (, uint afterPutAccBal) = c.Acc(address(this));
        uint afterPutCbal = address(c).balance;
        uint afterPutThisBal = address(this).balance;

        // Now attempt Collect(collectAmount)
        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // read final values
        (, uint finalAccBal) = c.Acc(address(this));
        uint finalCbal = address(c).balance;
        uint finalThisBal = address(this).balance;

        // If Collect did not revert AND it actually transferred value, then the holder balance and C balance
        // must have decreased by collectAmount and this contract's balance must have increased by collectAmount.
        // We cannot directly observe whether Collect's internal condition acc.balance>=MinSum etc. held; however,
        // any successful non-reverting Collect that performs the transfer will change balances as described.
        // So assert: either Collect reverted, or balances changed consistently by collectAmount, or nothing changed
        // because Put had reverted earlier leaving insufficient balance (covering case where Collect is a no-op).

        // Define didTransfer as the case where finalThisBal increased by exactly collectAmount compared to afterPutThisBal
        bool didTransfer = (finalThisBal == afterPutThisBal + collectAmount);

        // The general property: if Collect did not revert then either it performed the transfer (and balances moved by collectAmount)
        // OR it did not perform the transfer (no balances changed compared to afterPut) — but that second case should only occur if Collect's internal conditions failed
        // We capture that by allowing: collectReverted OR didTransfer OR (finalAccBal == afterPutAccBal && finalCbal == afterPutCbal && finalThisBal == afterPutThisBal)

        assert(collectReverted || didTransfer || (finalAccBal == afterPutAccBal && finalCbal == afterPutCbal && finalThisBal == afterPutThisBal));
    }

    // allow receiving Ether when C calls back
    receive() external payable {}
}

