contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run tries to withdraw _am after optionally funding the contract; it asserts that when Collect does not revert,
    // the holder balance recorded in c decreases by exactly _am and this contract's balance increases by exactly _am.
    function run(uint fundAmount, uint lockTime, uint _am) public payable {
        require(address(this).balance >= fundAmount);

        // initial observed values
        (uint beforeBalance,,) = getAcc(c);
        uint cBalBefore = address(c).balance;
        uint myBalBefore = address(this).balance;

        // If fundAmount > 0, call Put to deposit into c on behalf of this test contract
        if (fundAmount > 0) {
            // ensure we send Ether from this contract
            c.Put{value: fundAmount}(lockTime);
        }

        // attempt Collect and record whether it reverted
        bool reverted;
        try c.Collect{value: 0}(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observed after-values
        (uint afterBalance,,) = getAcc(c);
        uint cBalAfter = address(c).balance;
        uint myBalAfter = address(this).balance;

        // If Collect did not revert, then the recorded holder balance must have decreased by exactly _am
        // and this contract's balance must have increased by exactly _am, and c's ether balance reflects that transfer.
        assert(reverted || (afterBalance + _am == beforeBalance && myBalAfter == myBalBefore + _am && cBalAfter + _am == cBalBefore));
    }

    // helper to read the public Acc mapping for this contract's address via the autogenerated getter
    function getAcc(C _c) internal view returns (uint balance, uint unlockTime, uint dummy) {
        // The autogenerated getter for mapping (address => Holder) public Acc
        // returns (uint unlockTime, uint balance) in the order of the struct members.
        // But because the struct in C is defined as (uint unlockTime; uint balance;), the getter returns (uint, uint).
        // To avoid compilation issues with tuple ordering, call the getter and map appropriately.
        (uint a, uint b) = _c.Acc(address(this));
        // a == unlockTime, b == balance
        return (b, a, 0);
    }

    receive() external payable {}
}

