    // run: optionally deposit via Put, then call Collect(_am). If Collect does not revert,
    // then recorded balance for this contract after the call is equal to before minus actual withdrawn amount,
    // and address(c).balance decreases by exactly that withdrawn amount. Since we can't read the actual
    // withdrawn value directly, we observe that if Collect succeeds then (beforeBalance >= afterBalance) and
    // c balance decreased by (beforeBalance - afterBalance) which is <= requested _am and equals the change in address(c).balance.
    function run(uint fundAmount, uint lockTime, uint _am) public payable {
        require(address(this).balance >= fundAmount);

        // read-before values
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint cBalBefore = address(c).balance;

        // optional deposit: must be a top-level state-changing call
        if (fundAmount > 0) {
            c.Put{value: fundAmount}(lockTime);
        }

        // Attempt Collect as a top-level call and record revert flag
        bool reverted;
        try c.Collect{value: 0}(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read-after values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint cBalAfter = address(c).balance;

        // If Collect did not revert then:
        // 1) recorded balance did not increase: afterBalance <= beforeBalance
        // 2) the drop in recorded balance (beforeBalance - afterBalance) is <= requested _am
        // 3) the contract's external balance decreased exactly by that recorded-drop amount: cBalBefore - cBalAfter == beforeBalance - afterBalance
        assert(reverted || (afterBalance <= beforeBalance
                             && (beforeBalance - afterBalance) <= _am
                             && (cBalBefore - cBalAfter) == (beforeBalance - afterBalance)));
