contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    // params: requested withdraw amount and a prior deposit amount to ensure there is balance to collect
    function run(uint priorLock, uint depositAmt, uint collectAmt) public payable {
        // ensure this test contract has enough ETH to send depositAmt
        require(address(this).balance >= depositAmt, "insufficient balance for deposit");

        // Make an initial Put to ensure the Acc for this contract has some balance and unlockTime in the future
        // We don't care about revert here; record whether deposit reverted
        bool depReverted;
        try c.Put{value: depositAmt}(priorLock) {
            depReverted = false;
        } catch {
            depReverted = true;
        }

        // Read balances and contract balance before attempting Collect
        (uint beforeUnlock, uint beforeRecBalance) = c.Acc(address(this));
        uint beforeContractBalance = address(c).balance;
        uint beforeSelf = address(this).balance;

        // Attempt Collect and observe whether it reverted
        bool collectReverted;
        try c.Collect(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        (uint afterUnlock, uint afterRecBalance) = c.Acc(address(this));
        uint afterContractBalance = address(c).balance;
        uint afterSelf = address(this).balance;

        // If Collect did not revert and the recorded balance decreased by some amount D > 0,
        // then this contract's balance must have increased by exactly D, and the contract's balance
        // must have decreased by at least D. We express this as a single assert.
        // Let D = beforeRecBalance - afterRecBalance (computed in uint safely because after<=before when Collect succeeds)
        uint decreased = 0;
        if (beforeRecBalance > afterRecBalance) {
            decreased = beforeRecBalance - afterRecBalance;
        }

        // Final assertion: either collect reverted OR (if recorded balance decreased) it corresponds to on-chain transfers
        assert(
            collectReverted || (
                // if recorded balance decreased, the external balance increased exactly by that amount
                (decreased == 0) || (
                    afterSelf == beforeSelf + decreased
                    && beforeContractBalance >= afterContractBalance
                    && (beforeContractBalance - afterContractBalance) >= decreased
                )
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run a Put with given lockTime and amount; check log updated when Put does not revert
    function run(uint lockTime, uint amount) public payable {
        require(address(this).balance >= amount);

        // read history length before
        uint lenBefore = c.LogFile().History.length;

        bool reverted;
        try c.Put{value: amount}(lockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read history length after and, if present, the last message
        uint lenAfter = c.LogFile().History.length;

        // If Put did not revert then a new History entry must have been appended
        // and its Sender must be this contract and Val must equal amount and Data == "Put".
        // Access LastMsg via public getter: LogFile.LastMsg is not public, but History is public.
        // Build condition accordingly.
        if (!reverted) {
            // require that an entry was appended
            assert(lenAfter == lenBefore + 1);
            (address sender, string memory data, uint val, uint time) = (
                c.LogFile().History(lenAfter - 1).Sender,
                c.LogFile().History(lenAfter - 1).Data,
                c.LogFile().History(lenAfter - 1).Val,
                c.LogFile().History(lenAfter - 1).Time
            );
            // general rule: last history entry matches this Put
            assert(sender == address(this) && val == amount && keccak256(bytes(data)) == keccak256(bytes("Put")));
        } else {
            // if reverted, no guarantee about history; but we must still reach a single assert per the template
            // assert a tautology relating lengths (no new entry was added)
            assert(lenAfter == lenBefore);
        }
    }

    receive() external payable {}
}

